DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `juegos_bibliotecas_BEFORE_INSERT` BEFORE INSERT ON `juegos_bibliotecas` FOR EACH ROW BEGIN
IF NEW.fecha_adquisicion > CURDATE() THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La fecha de adquisición no puede ser una fecha futura.';
    END IF;
END */;;
DELIMITER ;
