/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `actualizar_nivel_cuenta_BEFORE_INSERT` AFTER INSERT ON `juegos_bibliotecas` FOR EACH ROW BEGIN
    UPDATE Usuarios
    SET nivel_cuenta = nivel_cuenta + 1
    WHERE id_usuario = (SELECT id_usuario FROM Bibliotecas WHERE id_biblioteca = NEW.id_biblioteca);
END */;;
DELIMITER ;
