DROP TABLE IF EXISTS `reseñas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reseñas` (
  `id_resena` int NOT NULL,
  `id_juego` int DEFAULT NULL,
  `id_usuario` int DEFAULT NULL,
  `puntuacion` int NOT NULL,
  `comentario` text,
  `votos_positivos` int NOT NULL,
  `fecha_resena` date NOT NULL,
  PRIMARY KEY (`id_resena`),
  KEY `id_juego` (`id_juego`),
  KEY `reseñas_ibfk_2` (`id_usuario`),
  CONSTRAINT `reseñas_ibfk_1` FOREIGN KEY (`id_juego`) REFERENCES `juegos` (`id_juego`),
  CONSTRAINT `reseñas_ibfk_2` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

